$(function(){$("#name").change(function(e){_this=$(this);$.get("../chart_of_account/ajax_check_account_name.php",{name:$(this).val()},function(data){if(data!=""){setErrorAttr(_this);initError();$("#error").html(data)}else removeErrorAttr(_this)})});$("form#accounts").submit(function(){if(formErrorCheck(this)){nameToIdConvert();return true}return false})});